// fips140_ssh_kdf_smoke — the SSH KDF of RFC 4253 §7.2, i.e. the
// crypto/internal/fips140/ssh extraction.
//
// The KDF is K1 = HASH(K || H || X || session_id) and
// K(n+1) = HASH(K || H || K1 || … || Kn), truncated to the requested
// length. Every expectation is generated by an independent Python
// transcription of that recurrence; the shape is simple enough that the
// interesting failures are structural, so the test targets those:
//
//   * lengths at, below and well above one digest (16 / 32 / 64 with
//     SHA-256) — a KDF that forgets the feedback loop still gets the
//     first block right;
//   * all six direction tags, which is the only thing distinguishing
//     the six keys of a connection;
//   * three digest sizes, so nothing can hard-code 32.

#![no_std]
#![no_main]
#![allow(non_snake_case)]

extern crate alloc;
extern crate goish;

use alloc::vec::Vec;
use goish::crypto::internal::fips140::sha256;
use goish::crypto::internal::fips140::sha512;
use goish::crypto::internal::fips140::ssh;
use goish::crypto::sha1;
use goish::encoding::hex;
use goish::fmt;
use goish::goslice::slice;
use goish::hash::Hash;
use goish::types::byte;

use alloc::boxed::Box;

static mut FAILED: bool = false;

fn check(name: &str, got: goish::string, want: &str) {
    if got == goish::string::from(want) {
        fmt::Printf!("PASS: %s\n", goish::string::from(name));
    } else {
        fmt::Printf!(
            "FAIL: %s\n  got  %s\n  want %s\n",
            goish::string::from(name),
            got,
            goish::string::from(want)
        );
        unsafe { FAILED = true };
    }
}

fn unhex(s: &str) -> slice<byte> {
    let b = s.as_bytes();
    if b.len() % 2 != 0 {
        panic!("unhex: odd length");
    }
    let mut out: Vec<byte> = Vec::with_capacity(b.len() / 2);
    let mut i = 0;
    while i < b.len() {
        out.push(nib(b[i]) * 16 + nib(b[i + 1]));
        i += 2;
    }
    return slice::__from_vec(out);
}

fn nib(c: u8) -> byte {
    if c >= b'0' && c <= b'9' {
        return c - b'0';
    }
    if c >= b'a' && c <= b'f' {
        return c - b'a' + 10;
    }
    panic!("unhex: not a hex digit");
}

fn hx(s: &slice<byte>) -> goish::string {
    let r: &[byte] = s;
    return hex::EncodeToString(r);
}

fn newSHA1() -> Box<dyn Hash + Send + Sync> {
    return Box::new(sha1::New());
}

const KHEX: &str = "000102030405060708090a0b0c0d0e0f10";
const HHEX: &str = "7bde03b6174b06ac22d902ada587e02f46b15e82e96fcc34d951b86efe0642f8";

#[goish::main]
fn main() {
    let K = unhex(KHEX);
    let H = unhex(HHEX);
    // In a real handshake the session ID is the first exchange hash; here
    // it is H, which is what the reference used.
    let sid = H.clone();

    // ── SHA-256, server direction (tags B / D / F) ────────────────────
    let (iv, key, mac) = ssh::Keys(
        sha256::NewHash,
        &ssh::ServerKeys,
        K.clone(),
        H.clone(),
        sid.clone(),
        16,
        32,
        64,
    );
    check(
        "SHA-256 server IV (tag B, 16)",
        hx(&iv),
        "5bdc661c4c583b3f2e0570b5ec1a9a80",
    );
    check(
        "SHA-256 server key (tag D, 32)",
        hx(&key),
        "aee25634d5be98652a16a6a3c5818df59516f6a9679bce5b1c5dc9286a52475a",
    );
    // 64 bytes is two full feedback rounds past the first digest.
    check(
        "SHA-256 server MAC key (tag F, 64)",
        hx(&mac),
        "5c66a61700c1db1ae40869815616034e7a0f7047029f92bb650b72a52edcc65e\
         ae523340d0c766a0acee0639de8ad41c81e07f69c68617f7bec8bc910ed99a25",
    );

    // ── SHA-256, client direction (tags A / C / E) ────────────────────
    let (iv, key, mac) = ssh::Keys(
        sha256::NewHash,
        &ssh::ClientKeys,
        K.clone(),
        H.clone(),
        sid.clone(),
        16,
        24,
        20,
    );
    check(
        "SHA-256 client IV (tag A, 16)",
        hx(&iv),
        "d46184c68ec0a7c8050ee0c2541e8939",
    );
    check(
        "SHA-256 client key (tag C, 24)",
        hx(&key),
        "4f9eee83c227c3afd6cc062a9565fd75ecacee8f9d32d78f",
    );
    check(
        "SHA-256 client MAC key (tag E, 20)",
        hx(&mac),
        "f5da8c6c60b06c1b420cd2fd004533560b09de00",
    );

    // ── SHA-1: 20-byte digest, so every length lands differently ──────
    let (iv, key, mac) = ssh::Keys(
        newSHA1,
        &ssh::ServerKeys,
        K.clone(),
        H.clone(),
        sid.clone(),
        16,
        32,
        64,
    );
    check(
        "SHA-1 server IV",
        hx(&iv),
        "1d2dff366e78cf8d69b1d67ebdf77f47",
    );
    check(
        "SHA-1 server key",
        hx(&key),
        "a0a1771847a23bc8eb8d28046987d07fa39ebefa9477e33acfbaaf7e094a91fc",
    );
    check(
        "SHA-1 server MAC key",
        hx(&mac),
        "e5a87478715aee31ecf4c03650c0a56070c70ecac8d3087f5d00c509f1de1d06\
         1ad12d0b7635c9502a2cd48f0d6676dd4e380d39a7b94832611cde706cdcfd65",
    );

    // ── SHA-512: 64-byte digest, so a 64-byte key is exactly one block ─
    let (iv, key, mac) = ssh::Keys(
        sha512::NewHash,
        &ssh::ClientKeys,
        K.clone(),
        H.clone(),
        sid.clone(),
        16,
        24,
        20,
    );
    check(
        "SHA-512 client IV",
        hx(&iv),
        "2dd6bdbd8eea5f0cdc7aef4ac3f2a979",
    );
    check(
        "SHA-512 client key",
        hx(&key),
        "a60ad7bd7529987b7f0b3e103ab51137796aa9f22950164e",
    );
    check(
        "SHA-512 client MAC key",
        hx(&mac),
        "60ddb1df50591b0458c6f4b2d239766a211e595a",
    );

    let (_, key, _) = ssh::Keys(
        sha512::NewHash,
        &ssh::ServerKeys,
        K.clone(),
        H.clone(),
        sid.clone(),
        16,
        64,
        20,
    );
    check(
        "SHA-512 server key, exactly one digest",
        hx(&key),
        "78664acd8110a401c8faa2e744e5a66032577bb7113d3a906b7daf1f9483d30c\
         6cf193ac7b5c24b2c5e05fd095a43836f1047e56df8e3b66ea6a66b68caa7a8f",
    );

    // A zero length must not consume a block.
    let (iv, _, _) = ssh::Keys(
        sha256::NewHash,
        &ssh::ServerKeys,
        K.clone(),
        H.clone(),
        sid,
        0,
        1,
        1,
    );
    check(
        "zero-length key is empty",
        fmt::Sprintf!("%d", iv.Len()),
        "0",
    );

    if unsafe { FAILED } {
        goish::syscall::Exit(1);
    }
    fmt::Printf!("fips140_ssh_kdf_smoke OK\n");
}
